// 由 tc-console 的 tools/globe/export-hub.mjs 生成，不要手改。地图素材：*.bin 是 gzip 后的 base64，clouds.png 是 data URL
// 来源（都是公有领域）：陆地 Natural Earth 50m/10m；地表颜色 NASA Blue Marble；夜光 NASA Black Marble 2016；
// 云 NASA Blue Marble 云图（Visible Earth 57747）；海拔 NOAA ETOPO1；星 Yale Bright Star Catalog 第 5 版
(() => {
  const BIN = {"land-points.bin":"","land-attr.bin":"","land-tone.bin":"","lights.bin":"","stars.bin":"","elev.bin":""};
  const CLOUDS = 'data:image/png;base64,';
  const raw = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));
  globalThis.TC_EMBED = {
    asset: f => BIN[f] ? new Response(new Blob([raw(BIN[f])]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer() : null,
    url: f => f === 'clouds.png' ? CLOUDS : null,
  };
})();
